WITH recent_stores AS (SELECT * FROM stores WHERE store_name LIKE '%Downt%' AND store_name IS NOT NULL), OpenedCohortSummary AS (SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, city, MIN(opened_date) AS min_opened_date, COUNT(*) AS num_stores FROM recent_stores GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END, city) SELECT opened_cohort, city, num_stores FROM OpenedCohortSummary WHERE num_stores < 7 ORDER BY 3 DESC, city, opened_cohort LIMIT 5
